import { css, CSSObject, FlattenSimpleInterpolation } from 'styled-components';

import Typography from '@dynatrace/strato-design-tokens/typography';

/**
 * All text styles that are available.
 * @deprecated - Will be removed.
 */
export const textStyleVariants = [
  /** Default text style, which should be used for longer continuous text. */
  'base',
  /** Emphasized (bold) text style, which should be used for longer continuous text. */
  'base-emphasized',
  /** Small text style, which should be used for smaller hints and labels. */
  'small',
  /** Small text style emphasized (bold), which should be used for.smaller hints and labels. */
  'small-emphasized',
] as const;

/**
 * @deprecated - Will be removed.
 */
export const fontStyleVariants = [
  /** Default font style that should be used for continous text. */
  'text',
  /** Monospaced text style, which should be used for code examples. */
  'code',
] as const;

/**
 * All the variants for our textStyles.
 * @deprecated - Will be removed.
 */
export type TextStyleVariantsType = (typeof textStyleVariants)[number];

/**
 * All the variants for our fontStyles.
 * @deprecated - Will be removed.
 */
export type FontStyleVariantsType = (typeof fontStyleVariants)[number];

