/**
 * Returns the appropriate css for the given textStyle.
 * This solution will be changed once StyleDictionary supports grouped tokens.
 * For now, we need to group the styles ourselves in separate constants.
 * @deprecated Prefer getTextStyle as an object for better tree shakeability
 */
export function getTextStyleCss(
  textStyle: TextStyleVariantsType,
  fontStyle: FontStyleVariantsType,
): FlattenSimpleInterpolation {
  if (fontStyle === 'code') {
    switch (textStyle) {
      case 'small-emphasized':
        return CodeSmallEmphasizedCss;
      case 'small':
        return CodeSmallCss;
      case 'base-emphasized':
        return CodeBaseEmphasizedCss;
      case 'base':
      default:
        return CodeBaseCss;
    }
  } else {
    switch (textStyle) {
      case 'small-emphasized':
        return TextSmallCss;
      case 'small':
        return TextSmallCss;
      case 'base-emphasized':
        return TextBaseEmphasizedCss;
      case 'base':
      default:
        return TextBaseCss;
    }
  }
}

/**
 * Returns the appropriate css for the given styles.
 * This solution will be changed once StyleDictionary supports grouped tokens.
 * For now, we need to group the styles ourselves in separate constants.
 * @deprecated Use the vanilla-extract 'textStyleCSS' instead.
 */
export function getTextStyle(
  textStyle: TextStyleVariantsType,
  fontStyle?: FontStyleVariantsType,
): CSSObject {
  if (fontStyle === 'code') {
    switch (textStyle) {
      case 'small-emphasized':
        return CodeSmallEmphasizedStyle;
      case 'small':
        return CodeSmallStyle;
      case 'base-emphasized':
        return CodeBaseEmphasizedStyle;
      case 'base':
      default:
        return CodeBaseStyle;
    }
  } else {
    switch (textStyle) {
      case 'small-emphasized':
        return TextSmallEmphasizedStyle;
      case 'small':
        return TextSmallStyle;
      case 'base-emphasized':
        return TextBaseEmphasizedStyle;
      case 'base':
      default:
        return TextBaseStyle;
    }
  }
}
